  1→<script lang="ts">
  2→import type { AggregatedMessage } from '@kynetic/shared/aggregated-message';
  3→import { ChevronDown } from 'lucide-svelte';
  4→import { onMount, tick } from 'svelte';
  5→import ChatInput from '$lib/components/chat/ChatInput.svelte';
  6→import ChatMessage from '$lib/components/chat/ChatMessage.svelte';
  7→import ThinkingIndicator from '$lib/components/chat/ThinkingIndicator.svelte';
  8→import ErrorBoundary from '$lib/components/common/ErrorBoundary.svelte';
  9→
 10→/** Status of an optimistic message */
 11→type OptimisticStatus = 'sending' | 'sent' | 'failed';
 12→
 13→/** Extended message type with optimistic status for UI rendering */
 14→type OptimisticAggregatedMessage = AggregatedMessage & {
 15→  optimisticStatus?: OptimisticStatus;
 16→  tempId?: string;
 17→};
 18→
 19→interface Props {
 20→  /** Session ID for display purposes */
 21→  sessionId: string;
 22→  /** Aggregated messages to display */
 23→  messages: OptimisticAggregatedMessage[];
 24→  /** Session creation time for duration display */
 25→  createdAt: string;
 26→  /** Callback when user sends a message */
 27→  onSendMessage: (content: string) => void;
 28→  /** Whether the input is enabled */
 29→  canSendMessages?: boolean;
 30→  /** Callback to retry a failed optimistic message */
 31→  onRetryMessage?: (tempId: string) => void;
 32→  /** Callback to dismiss a failed optimistic message */
 33→  onDismissMessage?: (tempId: string) => void;
 34→}
 35→
 36→const {
 37→  sessionId,
 38→  messages,
 39→  createdAt,
 40→  onSendMessage,
 41→  canSendMessages = true,
 42→  onRetryMessage,
 43→  onDismissMessage,
 44→}: Props = $props();
 45→
 46→let messagesContainer: HTMLDivElement;
 47→let shouldAutoScroll = $state(true);
 48→let scrollRafId: number | null = null;
 49→let userScrolling = $state(false);
 50→let scrollTimeout: ReturnType<typeof setTimeout> | null = null;
 51→let newContentCount = $state(0);
 52→let lastMessageCount = $state(0);
 53→
 54→// Check prefers-reduced-motion once on mount
 55→let prefersReducedMotion = $state(false);
 56→
 57→// Check if agent is currently "thinking" - last message is from user without agent response
 58→const isThinking = $derived(() => {
 59→  if (messages.length === 0) return false;
 60→  const lastMessage = messages[messages.length - 1];
 61→  return lastMessage.type === 'user_message';
 62→});
 63→
 64→// Check if any message is currently streaming
 65→const isStreaming = $derived(() => {
 66→  return messages.some((m) => m.is_streaming);
 67→});
 68→
 69→// Show jump button when scrolled up and content is streaming
 70→const showJumpButton = $derived(() => !shouldAutoScroll && isStreaming());
 71→
 72→// Calculate session duration
 73→const sessionDuration = $derived(() => {
 74→  const start = new Date(createdAt);
 75→  const now = new Date();
 76→  const diffMs = now.getTime() - start.getTime();
 77→  const diffMins = Math.floor(diffMs / 60000);
 78→  const diffSecs = Math.floor((diffMs % 60000) / 1000);
 79→  return `${diffMins}m ${diffSecs}s`;
 80→});
 81→
 82→// Filter out empty messages (messages with no content except tool_call which has no content field)
 83→const filteredMessages = $derived(
 84→  messages.filter((m) => {
 85→    // Tool calls always shown (they have input/output, not content)
 86→    if (m.type === 'tool_call') return true;
 87→    // Text-based messages need content
 88→    const content = (m as { content?: string }).content;
 89→    return content && content.trim().length > 0;
 90→  }),
 91→);
 92→
 93→// Debounced smooth scroll to bottom using requestAnimationFrame
 94→function scrollToBottom() {
 95→  if (scrollRafId !== null) {
 96→    cancelAnimationFrame(scrollRafId);
 97→  }
 98→  scrollRafId = requestAnimationFrame(() => {
 99→    scrollRafId = null;
100→    if (messagesContainer) {
101→      messagesContainer.scrollTo({
102→        top: messagesContainer.scrollHeight,
103→        behavior: prefersReducedMotion ? 'auto' : 'smooth',
104→      });
105→    }
106→  });
107→}
108→
109→// Jump to bottom and re-enable auto-scroll
110→function jumpToBottom() {
111→  shouldAutoScroll = true;
112→  newContentCount = 0;
113→  scrollToBottom();
114→}
115→
116→// Auto-scroll to bottom when new messages arrive or content changes
117→$effect(() => {
118→  // Track filtered messages to detect changes (length and last message content)
119→  const lastMsg = filteredMessages[filteredMessages.length - 1];
120→  const _ =
121→    lastMsg?.type === 'agent_message' || lastMsg?.type === 'agent_thought'
122→      ? (lastMsg as { content?: string }).content?.length
123→      : filteredMessages.length;
124→
125→  // Skip auto-scroll if user is actively scrolling
126→  if (shouldAutoScroll && !userScrolling && messagesContainer) {
127→    tick().then(scrollToBottom);
128→  }
129→});
130→
131→// Track new content arriving while scrolled up
132→$effect(() => {
133→  const currentCount = filteredMessages.length;
134→  if (!shouldAutoScroll && currentCount > lastMessageCount) {
135→    newContentCount += currentCount - lastMessageCount;
136→  }
137→  lastMessageCount = currentCount;
138→});
139→
