   183→
   184→			<!-- Output section (only when available) -->
   185→			{#if formattedOutput}
   186→				<div>
   187→					<div class="text-[10px] uppercase tracking-wide text-zinc-600 mb-1">Output</div>
   188→					<pre class="{showFullOutput ? 'max-h-none' : 'max-h-48'} overflow-auto rounded bg-zinc-950 p-2 text-xs {toolStatus === 'failed' ? 'text-red-400' : 'text-zinc-400'}">{displayedOutput}</pre>
   189→					{#if isOutputLarge}
   190→						<button
