/**
 * WebSocket Manager Types
 *
 * Internal types for WebSocketManager connection state and management.
 * AC: @web-dashboard ac-28, ac-29, ac-30, ac-31, ac-32, ac-33
 */

/**
 * WebSocket connection state
 * AC: @web-dashboard ac-28, ac-29
 */
export type ConnectionState = 'disconnected' | 'connecting' | 'connected' | 'reconnecting';

/**
 * Subscription topic
 * AC: @web-dashboard ac-32
 */
export interface Subscription {
	topic: string;
	subscribed_at: Date;
}

/**
 * Connection statistics
 * AC: @web-dashboard ac-28
 */
export interface ConnectionStats {
	connect_count: number;
	reconnect_count: number;
	last_connected_at: Date | null;
	last_disconnected_at: Date | null;
}

/**
 * Event handler callback
 * AC: @web-dashboard ac-33
 */
export type EventHandler = (event: any) => void;

/**
 * State change handler callback
 * AC: @web-dashboard ac-29
 */
export type StateChangeHandler = (state: ConnectionState) => void;

/*
 * Design Token Contract
 *
 * Ported from imgen design-system token-contract.css.
 * Defines the --design-* CSS custom properties that provide a consistent
 * visual language across all kspec web UI views.
 *
 * Colors (16): oklch color space for perceptual uniformity
 * Radii (4): border-radius scale
 * Spacing (7): spacing scale
 * Z-Index (7): layer stack
 * Fonts (3): typography families
 * Status (7): task status semantic colors
 */

:root {
