/**
 * WebSocket Manager for Hub UI
 *
 * Handles WebSocket connection to Hub with:
 * - Automatic reconnection with exponential backoff
 * - Topic subscription management
 * - Message routing to handlers
 * - Ping/pong heartbeat handling
 */

import type { CommandAck, HubCommand, HubEvent, PingEventData } from './types.js';
import { TOPIC_SYSTEM } from './types.js';

// =============================================================================
// Types
// =============================================================================

export type ConnectionState = 'disconnected' | 'connecting' | 'connected' | 'reconnecting';

export type EventHandler<T = unknown> = (event: HubEvent<T>) => void;
export type StateChangeHandler = (state: ConnectionState) => void;
export type ErrorHandler = (error: Error) => void;

interface PendingRequest {
  resolve: (value: CommandAck) => void;
  reject: (error: Error) => void;
  timeout: ReturnType<typeof setTimeout>;
}

// =============================================================================
// WebSocket Manager
// =============================================================================

/**
 * WebSocket manager with reconnection and topic subscription.
 */
export class WebSocketManager {
  private ws: WebSocket | null = null;
  private url: string;
  private reconnectAttempts = 0;
  private maxReconnectAttempts = 10;
  private reconnectTimer: ReturnType<typeof setTimeout> | null = null;
  private requestCounter = 0;

  // Subscriptions and handlers
  private subscriptions = new Set<string>();
  private topicHandlers = new Map<string, Set<EventHandler>>();
  private stateChangeHandlers = new Set<StateChangeHandler>();
  private errorHandlers = new Set<ErrorHandler>();
  private pendingRequests = new Map<string, PendingRequest>();

  // State
  private _state: ConnectionState = 'disconnected';
  private _lastSeq = 0;

  constructor(url = 'ws://localhost:8766/ws/ui') {
    this.url = url;
  }

  // =============================================================================
  // Public API
  // =============================================================================

  /**
   * Get current connection state.
   */
  get state(): ConnectionState {
    return this._state;
  }

  /**
   * Get last received sequence number.
   */
  get lastSeq(): number {
    return this._lastSeq;
  }

  /**
   * Check if connected.
   */
  get isConnected(): boolean {
    return this._state === 'connected';
  }

  /**
   * Configure the WebSocket URL.
   */
  setUrl(url: string): void {
    this.url = url;
  }

  /**
   * Connect to the WebSocket server.
   */
  connect(): void {
    if (this.ws && (this._state === 'connected' || this._state === 'connecting')) {
      return;
    }

    this.setState(this.reconnectAttempts > 0 ? 'reconnecting' : 'connecting');

    try {
      this.ws = new WebSocket(this.url);
      this.ws.onopen = () => this.handleOpen();
      this.ws.onmessage = (e) => this.handleMessage(e);
      this.ws.onclose = (e) => this.handleClose(e);
      this.ws.onerror = (e) => this.handleError(e);
    } catch (error) {
      this.emitError(error instanceof Error ? error : new Error(String(error)));
      this.scheduleReconnect();
    }
  }

  /**
   * Disconnect from the WebSocket server.
   */
  disconnect(): void {
    this.clearReconnectTimer();
    this.reconnectAttempts = 0;

    if (this.ws) {
      this.ws.onclose = null; // Prevent reconnection
      this.ws.close(1000, 'Client disconnect');
