  // Will be sent on reconnect
  return { ack: true, action: 'subscribe', success: true };
}

/**
 * Unsubscribe from topics.
 */
async unsubscribe(topics: string[]): Promise<CommandAck> {
  const existingTopics = topics.filter((t) => this.subscriptions.has(t));
  if (existingTopics.length === 0) {
    return { ack: true, action: 'unsubscribe', success: true };
  }

  // Remove from local tracking
  for (const t of existingTopics) {
    this.subscriptions.delete(t);
  }

  // Send command if connected
  if (this.isConnected) {
    return this.sendCommand({ action: 'unsubscribe', topics: existingTopics });
  }

  return { ack: true, action: 'unsubscribe', success: true };
}

/**
 * Send a message to a session.
 */
async sendSessionMessage(sessionId: string, content: string): Promise<CommandAck> {
  if (!this.isConnected) {
    throw new Error('Not connected');
  }
  return this.sendCommand({
    action: 'session.message',
    session_id: sessionId,
    payload: { content },
  });
}

/**
 * Send an interaction response.
 */
async sendInteractionResponse(
  sessionId: string,
  interactionId: string,
  response: unknown,
): Promise<CommandAck> {
  if (!this.isConnected) {
    throw new Error('Not connected');
  }
  return this.sendCommand({
    action: 'session.interaction_response',
    session_id: sessionId,
    payload: { interaction_id: interactionId, response },
  });
}

/**
 * Register a handler for events on a topic.
 * Returns an unsubscribe function.
 */
onTopic<T = unknown>(topic: string, handler: EventHandler<T>): () => void {
  if (!this.topicHandlers.has(topic)) {
    this.topicHandlers.set(topic, new Set());
  }
  this.topicHandlers.get(topic)?.add(handler as EventHandler);

  return () => {
    const handlers = this.topicHandlers.get(topic);
    if (handlers) {
      handlers.delete(handler as EventHandler);
      if (handlers.size === 0) {
        this.topicHandlers.delete(topic);
      }
    }
  };
}

/**
 * Register a connection state change handler.
 * Returns an unsubscribe function.
 */
onStateChange(handler: StateChangeHandler): () => void {
  this.stateChangeHandlers.add(handler);
  return () => this.stateChangeHandlers.delete(handler);
}

/**
 * Register an error handler.
 * Returns an unsubscribe function.
 */
onError(handler: ErrorHandler): () => void {
  this.errorHandlers.add(handler);
  return () => this.errorHandlers.delete(handler);
}

// =============================================================================
// Internal Handlers
// =============================================================================

