/**
 * HTML sanitization utilities for XSS protection.
 *
 * LLM output should be treated as untrusted content due to prompt injection attacks.
 * All markdown-rendered HTML must be sanitized before insertion into the DOM.
 *
 * @see https://developer.chrome.com/docs/ai/render-llm-responses
 */
import DOMPurify from 'dompurify';

/**
 * Allowed HTML tags for chat message rendering.
 * Supports basic formatting, code blocks, lists, links, blockquotes, and tables.
 */
const ALLOWED_TAGS = [
  // Text formatting
  'p',
  'br',
  'b',
  'i',
  'em',
  'strong',
  'u',
  's',
  'del',
  // Headings (for structured content)
  'h1',
  'h2',
  'h3',
  'h4',
  'h5',
  'h6',
  // Code
  'code',
  'pre',
  // Lists
  'ul',
  'ol',
  'li',
  // Links
  'a',
  // Blockquotes
  'blockquote',
  // Tables
  'table',
  'thead',
  'tbody',
  'tfoot',
  'tr',
  'th',
  'td',
  'caption',
  'colgroup',
  'col',
  // Horizontal rules
  'hr',
  // Semantic
  'span',
  'div',
  // Math equations (streaming-markdown custom elements, rendered by KaTeX)
  'equation-block',
  'equation-inline',
] as const;

/**
 * Allowed HTML attributes.
 * Limited to safe attributes that don't enable script execution.
 */
const ALLOWED_ATTR = [
  'href',
  'title',
  'class',
  'target',
  'rel',
  // For accessibility
  'aria-label',
  'aria-hidden',
  'role',
  // For markdown features (code highlighting, math rendering)
  'data-language',
  'data-katex',
] as const;

/**
 * DOMPurify configuration for chat messages.
 */
const SANITIZE_CONFIG = {
  ALLOWED_TAGS: [...ALLOWED_TAGS],
  ALLOWED_ATTR: [...ALLOWED_ATTR],
  // Ensure links open safely
  ADD_ATTR: ['target', 'rel'],
  // Allow data-* attributes (safe, don't execute scripts) for features like data-katex
  ALLOW_DATA_ATTR: true,
  ALLOW_UNKNOWN_PROTOCOLS: false,
  // Custom element handling required for streaming-markdown's equation elements.
  // Without this, DOMPurify silently removes ALL custom elements even if in ALLOWED_TAGS.
  // See: https://github.com/cure53/DOMPurify/issues/596
  CUSTOM_ELEMENT_HANDLING: {
    tagNameCheck: /^equation-(block|inline)$/,
    attributeNameCheck: /^(class|data-katex)$/,
    allowCustomizedBuiltInElements: false,
  },
};

/**
 * Sanitizes HTML content to prevent XSS attacks.
 *
 * @param dirtyHtml - Untrusted HTML string (e.g., from markdown rendering)
 * @returns Sanitized HTML safe for insertion into DOM
 *
 * @example
 * ```ts
 * const clean = sanitizeHtml('<script>alert("xss")</script><b>Hello</b>');
 * // Returns: '<b>Hello</b>'
 * ```
 */
export function sanitizeHtml(dirtyHtml: string): string {
  if (!dirtyHtml) return '';

  const clean = DOMPurify.sanitize(dirtyHtml, SANITIZE_CONFIG) as string;

  // Ensure all links have safe attributes
  return clean.replace(/<a\s+([^>]*href="[^"]*"[^>]*)>/gi, (_match: string, attrs: string) => {
    // If target/rel not present, add them for external links
    if (!attrs.includes('target=')) {
      attrs += ' target="_blank"';
    }
    if (!attrs.includes('rel=')) {
      attrs += ' rel="noopener noreferrer"';
    }
    return `<a ${attrs}>`;
  });
}

/**
 * Checks if a string contains potentially dangerous HTML.
 * Useful for testing and validation.
 *
 * @param html - HTML string to check
 * @returns true if the HTML contains potentially dangerous content
 */
export function containsDangerousHtml(html: string): boolean {
  if (!html) return false;

  const sanitized = DOMPurify.sanitize(html, SANITIZE_CONFIG) as string;
  // If sanitization changed the content, it contained dangerous elements
  return sanitized !== html;
}

/**
 * Lazy-loaded Mermaid diagram renderer.
 *
 * Mermaid is loaded on-demand to minimize initial bundle size.
 * The library is only fetched when a mermaid code block is detected.
 */

let mermaidPromise: Promise<typeof import('mermaid')> | null = null;

/**
 * Lazy-load the mermaid library.
 * Returns a cached promise if already loading/loaded.
 */
export async function loadMermaid() {
  if (!mermaidPromise) {
    mermaidPromise = import('mermaid').then((m) => {
      m.default.initialize({
        startOnLoad: false,
        theme: 'dark',
        securityLevel: 'strict',
        // Suppress console logs from mermaid
        logLevel: 'error' as const,
      });
      return m;
    });
  }
  return mermaidPromise;
}

/** Counter for unique diagram IDs */
let diagramCounter = 0;

/**
 * Render a mermaid diagram into an element.
 *
 * @param element - The container element to render into
 * @param code - The mermaid diagram code
 * @throws Error if rendering fails (invalid syntax, etc.)
 */
export async function renderMermaid(element: HTMLElement, code: string): Promise<void> {
  const mermaid = await loadMermaid();

  // Generate unique ID for this diagram
  const id = `mermaid-${Date.now()}-${diagramCounter++}`;

  const { svg } = await mermaid.default.render(id, code);
  element.innerHTML = svg;
}

/**
 * Check if a language identifier indicates a mermaid diagram.
 */
export function isMermaidLanguage(language: string | undefined): boolean {
  return language?.toLowerCase() === 'mermaid';
}

