   135→    if (success) {
   136→      this.sendAck(ws, command.request_id, true);
   137→      console.log(`[ws] ${sessionId} subscribed to: ${topics.join(', ')}`);
   138→    } else {
   139→      this.sendAck(ws, command.request_id, false, 'not_found', 'Session not found');
   140→    }
   141→  }
   142→
   143→  /**
   144→   * Handle unsubscribe command
   145→   */
   146→  private handleUnsubscribe(ws: ServerWebSocket<ConnectionData>, command: WebSocketCommand) {
   147→    const topics = command.payload?.topics;
   148→
   149→    if (!topics || !Array.isArray(topics) || topics.length === 0) {
   150→      this.sendAck(ws, command.request_id, false, 'validation_error', 'Missing or invalid topics array');
   151→      return;
   152→    }
   153→
   154→    const sessionId = this.resolveSessionId(ws);
   155→    const success = sessionId ? this.pubsub.unsubscribe(sessionId, topics) : false;
   156→
   157→    if (success) {
   158→      this.sendAck(ws, command.request_id, true);
   159→      console.log(`[ws] ${sessionId} unsubscribed from: ${topics.join(', ')}`);
   160→    } else {
   161→      this.sendAck(ws, command.request_id, false, 'not_found', 'Session not found');
   162→    }
   163→  }
   164→
   165→  /**
   166→   * Handle ping command (application-level ping, not WebSocket frame)
   167→   */
   168→  private handlePing(ws: ServerWebSocket<ConnectionData>, command: WebSocketCommand) {
   169→    this.sendAck(ws, command.request_id, true);
   170→  }
   171→
   172→  private resolveSessionId(ws: ServerWebSocket<ConnectionData>): string | undefined {
   173→    const data = ws.data as { id?: unknown } | undefined;
   174→    const contextId = typeof data?.id === 'string' ? data.id : undefined;
   175→    return this.pubsub.getSessionIdBySocket(ws, contextId);
   176→  }
   177→
   178→  /**
   179→   * Send ack response
   180→   * AC: @api-contract ac-27
   181→   */
   182→  private sendAck(
   183→    ws: ServerWebSocket<ConnectionData>,
   184→    request_id: string | undefined,
   185→    success: boolean,
   186→    error?: string,
   187→    details?: string
   188→  ) {
   189→    const ack: CommandAck = {
   190→      ack: true,
   191→      request_id,
   192→      success,
   193→      error,
   194→      details
   195→    };
   196→
   197→    ws.send(JSON.stringify(ack));
   198→  }
   199→}
   200→
