   * Get all connections (for heartbeat checks)
   */
  getAllConnections(): Map<string, ServerWebSocket<ConnectionData>> {
    return this.connections;
  }

  /**
   * Get connection count
   */
  getConnectionCount(): number {
    return this.connections.size;
  }
