    : `${String(seq).padStart(6, "0")}-${fieldLabel}-${randomUUID()}.blob`;
  const relativePath = path.posix.join(BLOBS_DIR, fileName);
  if (!context.dryRun) {
    if (!context.ensuredDir) {
