## 11. STREAMING MESSAGE STORE

**File:** `/home/chapel/Projects/kynetic-internal/packages/hub-ui/src/lib/state/streaming-messages.svelte.ts`

**API:**
```typescript
const store = createStreamingStore(sessionId);

// Handle raw ACP events
store.handleEvent(hubEvent);

// Handle pre-aggregated semantic events (preferred)
store.handleSemanticEvent(messageManagerEvent);

// Hydrate from REST API
const state = hydrateFromMessages(sessionId, messages, sessionMeta);
store.replaceState(state);

// Clear all state
store.clear();

// Reset after reconnection
store.resetSequenceTracking();

// Access reactive messages
const messages = store.messages;  // AggregatedMessage[]
const meta = store.sessionMeta;   // SessionMeta
```

**Message Types in Store:**
```typescript
type AggregatedMessage = 
  | UserMessage       // { type: 'user_message', content, started_at, is_streaming }
  | AgentMessage      // { type: 'agent_message', content, started_at, is_streaming }
  | AgentThought      // { type: 'agent_thought', content, started_at, is_streaming }
  | ToolCall          // { type: 'tool_call', tool, tool_call_id, input, output, status, is_streaming }
```

**Key State Tracking:**
- `turnIndex`, `blockIndex` - derived from message IDs
- `activeMessageId` - current streaming text message (NOT tool calls)
- `pendingTools` - Map<tool_call_id → message_id> for tools in progress
- `lastSeqProcessed` - for deduplication after reconnection

---

## 12. AUTO-SCROLL UTILITIES & HOOKS

**ChatPanel Pattern:**
```typescript
let shouldAutoScroll = $state(true);
let scrollRafId: number | null = null;
let userScrolling = $state(false);

function handleScroll() {
  const { scrollTop, scrollHeight, clientHeight } = messagesContainer;
  const totalScrollable = scrollHeight - clientHeight;
  const distanceFromBottom = scrollHeight - scrollTop - clientHeight;

  // Smart threshold
  if (totalScrollable < 100) {
    shouldAutoScroll = distanceFromBottom < 5;  // Tight
  } else {
    shouldAutoScroll = distanceFromBottom < 100;  // Forgiving
  }

  // Reset new content count on scroll to bottom
  if (shouldAutoScroll) {
    newContentCount = 0;
  }
}

function scrollToBottom() {
  if (scrollRafId !== null) {
    cancelAnimationFrame(scrollRafId);
  }
  scrollRafId = requestAnimationFrame(() => {
    if (messagesContainer) {
      messagesContainer.scrollTo({
        top: messagesContainer.scrollHeight,
        behavior: prefersReducedMotion ? 'auto' : 'smooth',
      });
    }
  });
}

// Auto-scroll effect
$effect(() => {
  // Depend on message changes
  const lastMsg = filteredMessages[filteredMessages.length - 1];

  if (shouldAutoScroll && !userScrolling && messagesContainer) {
    tick().then(scrollToBottom);
  }
});
```

**MiniTerminal Pattern:**
```typescript
let autoScroll = $state(true);

function handleScroll(e: Event) {
  const target = e.target as HTMLDivElement;
  const isAtBottom = target.scrollHeight - target.scrollTop - target.clientHeight < 10;
  autoScroll = isAtBottom;
}

$effect(() => {
  // Depend on display lines
  displayLines;

  if (autoScroll && scrollContainer) {
    requestAnimationFrame(() => {
      if (scrollContainer) {
        scrollContainer.scrollTop = scrollContainer.scrollHeight;
      }
    });
  }
});
```

**Key Differences:**
- ChatPanel: smooth scroll, respects prefers-reduced-motion, smart threshold
- MiniTerminal: instant scroll, simpler threshold (10px from bottom)

