  3→  AC: @ui-task-board ac-6 — Action buttons: Start, Submit, Complete, Block, Add Note.
  4→-->
  5→<script lang="ts">
  6→	import type { TaskDetail } from '@kynetic-ai/shared';
  7→	import { base } from '$app/paths';
  8→	import {
  9→		fetchTask,
 10→		startTask,
 11→		submitTask,
 12→		completeTask,
 13→		blockTask,
 14→		addTaskNote
 15→	} from '$lib/api';
 16→	import { isStaticMode, ReadOnlyModeError } from '$lib/stores/mode.svelte';
 17→	import * as Dialog from '$lib/components/ui/dialog';
 18→	import { Badge } from '$lib/components/ui/badge';
 19→	import { Button } from '$lib/components/ui/button';
 20→	import { Textarea } from '$lib/components/ui/textarea';
 21→	import { Input } from '$lib/components/ui/input';
 22→	import { Separator } from '$lib/components/ui/separator';
 23→	import { getStatusClasses, formatAge } from './board-utils';
 24→
 25→	let {
 26→		open = $bindable(false),
 27→		taskRef = $bindable<string | null>(null),
 28→		onTaskUpdated
 29→	}: {
 30→		open?: boolean;
 31→		taskRef?: string | null;
 32→		onTaskUpdated?: () => void;
 33→	} = $props();
 34→
 35→	let task = $state<TaskDetail | null>(null);
 36→	let loading = $state(false);
 37→	let error = $state('');
 38→	let actionError = $state('');
 39→	let isSubmitting = $state(false);
 40→
 41→	// Note form
 42→	let noteContent = $state('');
 43→
 44→	// Block/Complete reason form
 45→	let reasonInput = $state('');
 46→	let showReasonFor = $state<'block' | 'complete' | null>(null);
 47→
 48→	$effect(() => {
 49→		if (open && taskRef) {
 50→			loadTask(taskRef);
 51→		} else if (!open) {
 52→			task = null;
 53→			error = '';
 54→			actionError = '';
 55→			noteContent = '';
 56→			reasonInput = '';
 57→			showReasonFor = null;
 58→		}
 59→	});
 60→
 61→	async function loadTask(ref: string) {
 62→		loading = true;
 63→		error = '';
 64→		try {
 65→			task = await fetchTask(ref);
 66→		} catch (err) {
 67→			error = err instanceof Error ? err.message : 'Failed to load task';
 68→		} finally {
 69→			loading = false;
 70→		}
 71→	}
 72→
 73→	async function reloadAndNotify() {
 74→		if (task) {
 75→			task = await fetchTask(task._ulid);
 76→		}
 77→		onTaskUpdated?.();
 78→	}
 79→
 80→	async function handleAction(action: () => Promise<void>) {
 81→		isSubmitting = true;
 82→		actionError = '';
 83→		try {
 84→			await action();
 85→			await reloadAndNotify();
 86→		} catch (err) {
 87→			if (err instanceof ReadOnlyModeError) {
 88→				actionError = err.message;
 89→			} else {
 90→				actionError = err instanceof Error ? err.message : 'Action failed';
 91→			}
 92→		} finally {
 93→			isSubmitting = false;
 94→		}
 95→	}
 96→
 97→	function handleStart() {
 98→		if (!task) return;
 99→		handleAction(() => startTask(task!._ulid));
100→	}
101→
102→	function handleSubmit() {
103→		if (!task) return;
104→		handleAction(() => submitTask(task!._ulid));
105→	}
106→
107→	function handleComplete() {
108→		if (!task || !reasonInput.trim()) return;
109→		const reason = reasonInput.trim();
110→		handleAction(async () => {
111→			await completeTask(task!._ulid, reason);
112→			reasonInput = '';
113→			showReasonFor = null;
114→		});
115→	}
116→
117→	function handleBlock() {
118→		if (!task || !reasonInput.trim()) return;
119→		const reason = reasonInput.trim();
120→		handleAction(async () => {
121→			await blockTask(task!._ulid, reason);
122→			reasonInput = '';
123→			showReasonFor = null;
124→		});
125→	}
126→
127→	function handleAddNote() {
128→		if (!task || !noteContent.trim()) return;
129→		const content = noteContent.trim();
130→		handleAction(async () => {
131→			await addTaskNote(task!._ulid, content);
132→			noteContent = '';
133→		});
134→	}
135→
136→	function formatDate(dateStr: string): string {
137→		return new Intl.DateTimeFormat('en-US', {
138→			month: 'short',
139→			day: 'numeric',
140→			hour: '2-digit',
141→			minute: '2-digit'
142→		}).format(new Date(dateStr));
143→	}
144→
145→	let statusInfo = $derived(task ? getStatusClasses(task.status) : null);
146→	let slug = $derived(task?.slugs?.[0] ?? task?._ulid?.slice(0, 8) ?? '');
