   138→
   139→      if (body.action === 'start') {
   140→        let engine = engines.get(projectDir);
   141→        if (engine?.getStatus().running) {
   142→          return { dispatch_enabled: true, reason: 'Already running' };
   143→        }
   144→
   145→        engine = createEngine(projectDir, pubsub);
   146→        engines.set(projectDir, engine);
   147→        await engine.start();
   148→
   149→        return { dispatch_enabled: true };
   150→      } else {
   151→        const engine = engines.get(projectDir);
   152→        if (!engine) {
   153→          return { dispatch_enabled: false, reason: 'No engine running' };
   154→        }
   155→
   156→        await engine.stop();
   157→        engines.delete(projectDir);
   158→
   159→        return { dispatch_enabled: false };
   160→      }
   161→    }, {
   162→      body: t.Object({
   163→        action: t.Union([t.Literal('start'), t.Literal('stop')]),
   164→      }),
   165→    })
   166→
   167→    // Start dispatch engine (legacy route)
   168→    .post('/dispatch/start', async ({ projectContext }) => {
   169→      const projectDir = projectContext.path;
   170→
   171→      let engine = engines.get(projectDir);
   172→      if (engine?.getStatus().running) {
   173→        return { started: false, reason: 'Already running', status: engine.getStatus() };
   174→      }
   175→
   176→      // AC: @agent-dispatch-engine ac-10 - pass kspecCliPath so task notes work from daemon-started engine
   177→      engine = createEngine(projectDir, pubsub);
   178→      engines.set(projectDir, engine);
   179→
   180→      await engine.start();
   181→
   182→      return { started: true, status: engine.getStatus() };
   183→    })
   184→
   185→    // Stop dispatch engine (legacy route)
   186→    .post('/dispatch/stop', async ({ projectContext }) => {
   187→      const projectDir = projectContext.path;
   188→      const engine = engines.get(projectDir);
   189→
   190→      if (!engine) {
   191→        return { stopped: false, reason: 'No engine running' };
   192→      }
   193→
   194→      await engine.stop();
   195→      engines.delete(projectDir);
   196→
   197→      return { stopped: true };
   198→    })
   199→
   200→    // Get dispatch engine status (internal format)
   201→    .get('/dispatch/status', ({ projectContext }) => {
   202→      const engine = engines.get(projectContext.path);
   203→
   204→      if (!engine) {
   205→        return {
   206→          running: false,
   207→          activeInvocations: 0,
   208→          queuedInvocations: 0,
   209→          invocations: [],
   210→        };
   211→      }
   212→
   213→      return engine.getStatus();
   214→    })
   215→
   216→    // AC: @daemon-agent-dispatch ac-5 - Public status endpoint
   217→    .get('/status', async ({ projectContext }) => {
   218→      const projectDir = projectContext.path;
   219→      const engineStatus = engines.get(projectDir)?.getStatus();
   220→
   221→      let agentDefinitions: Array<{ id: string; name: string; adapter: string }> = [];
   222→      try {
   223→        const ctx = await initContext(projectDir);
   224→        const meta = await loadMetaContext(ctx);
   225→        agentDefinitions = meta.agents.map((a) => ({
   226→          id: a.id,
   227→          name: a.name,
   228→          adapter: a.adapter ?? 'claude-agent-acp',
   229→        }));
   230→      } catch {
   231→        // Agent definitions unavailable — return empty array
   232→      }
   233→
   234→      return {
   235→        dispatch_enabled: engineStatus?.running ?? false,
   236→        active_invocations: engineStatus?.invocations?.map((inv) => ({
   237→          session_id: inv.sessionId,
   238→          agent_id: inv.agentId,
   239→          task_ref: inv.taskRef ?? null,
   240→          elapsed_ms: inv.elapsedMs,
   241→        })) ?? [],
   242→        queue_depth: engineStatus?.queuedInvocations ?? 0,
   243→        agent_definitions: agentDefinitions,
   244→      };
   245→    });
   246→}
   247→
   248→/**
   249→ * Get the dispatch engine for a project path (for integration with file watcher).
   250→ */
   251→export function getDispatchEngine(projectDir: string): DispatchEngine | undefined {
   252→  return engines.get(projectDir);
   253→}
   254→
   255→/**
   256→ * Stop all active dispatch engines. Called on daemon shutdown.
   257→ * AC: @agent-dispatch-engine ac-11 - daemon shutdown stops active engines
   258→ */
   259→export async function stopAllEngines(): Promise<void> {
   260→  const stopPromises: Promise<void>[] = [];
   261→  for (const [projectDir, engine] of engines) {
   262→    console.log(`[dispatch] Stopping engine for ${projectDir}...`);
   263→    stopPromises.push(
   264→      engine.stop().catch((err) => {
   265→        console.error(`[dispatch] Error stopping engine for ${projectDir}:`, err);
   266→      })
   267→    );
   268→  }
   269→  await Promise.all(stopPromises);
   270→  engines.clear();
   271→  console.log('[dispatch] All engines stopped');
   272→}
