  1045→export function deduplicatePhasedToolCalls(
  1046→  events: SessionEvent[],
  1047→): SessionEvent[] {
  1048→  // First pass: find toolCallIds that have a populated rawInput version
  1049→  const populatedToolCalls = new Map<string, number>(); // toolCallId → index
  1050→  for (let i = 0; i < events.length; i++) {
  1051→    const event = events[i];
  1052→    if (event.type !== "session.update") continue;
  1053→    const data = event.data as { update?: { sessionUpdate?: string; toolCallId?: string; tool_call_id?: string; id?: string; rawInput?: Record<string, unknown> } } | null;
  1054→    const update = data?.update;
  1055→    if (update?.sessionUpdate !== "tool_call") continue;
  1056→    const toolCallId = update.toolCallId || update.tool_call_id || update.id;
  1057→    if (!toolCallId) continue;
  1058→    const rawInput = update.rawInput;
  1059→    const hasContent = rawInput && Object.keys(rawInput).length > 0;
  1060→    if (hasContent) {
  1061→      populatedToolCalls.set(toolCallId, i);
  1062→    } else if (!populatedToolCalls.has(toolCallId)) {
  1063→      // First (empty) version - track it in case no populated version exists
  1064→      populatedToolCalls.set(toolCallId, i);
  1065→    }
  1066→  }
  1067→
  1068→  // Second pass: keep only the best version per toolCallId
  1069→  return events.filter((event, i) => {
  1070→    if (event.type !== "session.update") return true;
  1071→    const data = event.data as { update?: { sessionUpdate?: string; toolCallId?: string; tool_call_id?: string; id?: string; rawInput?: Record<string, unknown> } } | null;
